// Minimal TypeScript-ish example
interface RoutingStrategy { route(req: any, handlers: any): string }
class StrategyRegistry {
  private map = new Map<string, () => RoutingStrategy>()
  register(name: string, factory: () => RoutingStrategy) { this.map.set(name, factory) }
